    private void btnLeerArchivoActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLeerArchivoActionPerformed
        try {
            String ruta = txtRutaArchivo.getText().trim();

            if (ruta.isEmpty()) {
                throw new IllegalArgumentException("Por favor, ingrese la ruta o el nombre del archivo.");
            }

            String contenido = LectorArchivo.leerArchivo(ruta);

            txtAreaContenido.setText(contenido);

            javax.swing.JOptionPane.showMessageDialog(this, "Archivo leído con éxito.", "Lectura Exitosa", javax.swing.JOptionPane.INFORMATION_MESSAGE);

        } catch (IllegalArgumentException ex) {
            javax.swing.JOptionPane.showMessageDialog(this, ex.getMessage(), "Campo Vacío", javax.swing.JOptionPane.WARNING_MESSAGE);
        } catch (java.io.FileNotFoundException ex) {
            txtAreaContenido.setText("");
            javax.swing.JOptionPane.showMessageDialog(this, ex.getMessage(), "Error: Archivo No Encontrado", javax.swing.JOptionPane.ERROR_MESSAGE);
        } catch (java.io.IOException ex) {
            txtAreaContenido.setText("");
            javax.swing.JOptionPane.showMessageDialog(this, "Error al leer el archivo: " + ex.getMessage(), "Error E/S", javax.swing.JOptionPane.ERROR_MESSAGE);
        }
    }//GEN-LAST:event_btnLeerArchivoActionPerformed

